'use client';

import * as React from 'react';

import type { BillingProviderDescriptor } from '@/components/ui/billing-kit/providers';
import type { BillingHealth, CreditCode, CreditCodeDraft, CreditPack, CustomerSummary, DatabaseStanding, Meter, Plan, ProviderConnection } from '@/components/ui/billing-kit/types';
import type { BillingConsoleAction, BillingConsoleData, BillingConsoleSettings, BillingConsoleTheme, BillingConsoleView, EntitlementChange } from '@/components/ui/billing-console/types';

export type BillingConsoleContextValue = {
	data: BillingConsoleData;
	view: BillingConsoleView;
	views: BillingConsoleView[];
	setView: (view: BillingConsoleView) => void;
	emit: (action: BillingConsoleAction) => void;
	theme: BillingConsoleTheme;
	setTheme: (theme: BillingConsoleTheme) => void;
	/** The active provider's descriptor. */
	provider: BillingProviderDescriptor | undefined;
	/** The provider connection after any local connect or switch. */
	connection: ProviderConnection | undefined;
	/** Catalog after local toggles and saved entitlement edits; kept here so it survives view changes. */
	plans: Plan[];
	setPlans: React.Dispatch<React.SetStateAction<Plan[]>>;
	meters: Meter[];
	setMeters: React.Dispatch<React.SetStateAction<Meter[]>>;
	packs: CreditPack[];
	setPacks: React.Dispatch<React.SetStateAction<CreditPack[]>>;
	codes: CreditCode[];
	setCodes: React.Dispatch<React.SetStateAction<CreditCode[]>>;
	/** Present when the host can store codes. */
	saveCode: ((draft: CreditCodeDraft, existing?: CreditCode) => Promise<void>) | undefined;
	createCodes: ((drafts: CreditCodeDraft[]) => Promise<void>) | undefined;
	/** Persists entitlement edits; the catalog view applies them once this resolves. */
	saveEntitlements: (changes: EntitlementChange[]) => Promise<void>;
	holdDatabase: ((database: DatabaseStanding, note: string) => Promise<void>) | undefined;
	releaseDatabase: ((database: DatabaseStanding) => Promise<void>) | undefined;
	settings: BillingConsoleSettings;
	health: BillingHealth;
	checking: boolean;
	runCheck: () => void;
	setBillingEnabled: (enabled: boolean) => Promise<void>;
	setCreditRate: (creditsPerCent: number) => Promise<void>;
	openConnect: (providerId?: string) => void;
	standing: DatabaseStanding[];
	openCustomer: (customer: CustomerSummary) => void;
	planName: (planId: string) => string;
	meterName: (slug: string) => string;
};

export const BillingConsoleContext = React.createContext<BillingConsoleContextValue | null>(null);

export function useBillingConsole() {
	const context = React.useContext(BillingConsoleContext);
	if (!context) throw new Error('Billing console parts must be rendered inside <BillingConsole>.');
	return context;
}

'use client';

import * as React from 'react';

import { useControllableState } from '@/hooks/use-controllable-state';
import { BillingFormatProvider } from '@/components/ui/billing-kit/context';
import { CustomerDetailSheet, type GrantCreditsRequest } from '@/components/ui/billing-kit/customers';
import { DAY, humanize, isHealthFresh } from '@/components/ui/billing-kit/format';
import { ProviderConnectDialog } from '@/components/ui/billing-kit/provider';
import type { BillingHealth, CreditCode, CreditCodeDraft, CreditPack, CustomerSummary, DatabaseStanding, Meter, Plan, ProviderConnection } from '@/components/ui/billing-kit/types';
import { WorkspaceShell } from '@/components/ui/workspace-kit/shell';
import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { BillingConsoleContext, type BillingConsoleContextValue } from '@/components/ui/billing-console/billing-console-context';
import { ConsoleCatalogView } from '@/components/ui/billing-console/catalog-view';
import { ConsoleCustomersView } from '@/components/ui/billing-console/customers-view';
import { ConsoleOverviewView } from '@/components/ui/billing-console/overview-view';
import { ConsoleProviderView } from '@/components/ui/billing-console/provider-view';
import { BillingConsoleSidebar } from '@/components/ui/billing-console/sidebar';
import { ConsoleStandingView } from '@/components/ui/billing-console/standing-view';
import type { BillingConsoleAction, BillingConsoleData, BillingConsoleSettings, BillingConsoleTheme, BillingConsoleView, EntitlementChange } from '@/components/ui/billing-console/types';


type BillingConsoleProps = {
	data: BillingConsoleData;
	view?: BillingConsoleView;
	defaultView?: BillingConsoleView;
	onViewChange?: (view: BillingConsoleView) => void;
	/** Views the host can back. Defaults to all; `standing` only ever shows at platform scope. */
	views?: BillingConsoleView[];
	/** Persists entitlement edits (plan limits, meter limits, caps). Reject to keep them unsaved. */
	onSaveEntitlements?: (changes: EntitlementChange[]) => Promise<void> | void;
	/** Stores credentials and makes the provider active. Values are write-only. */
	onConnectProvider?: (providerId: string, values: Record<string, string>) => Promise<void> | void;
	/** Enqueues the readiness job. Resolve with the new verdict to show it. */
	onRunReadinessCheck?: () => Promise<BillingHealth | void>;
	/** Flips `enable_billing`. Reject with the gate's error to show it. */
	onToggleBilling?: (enabled: boolean) => Promise<void> | void;
	onCreditRateChange?: (creditsPerCent: number) => Promise<void> | void;
	onGrantCredits?: (request: GrantCreditsRequest) => Promise<void> | void;
	/**
	 * Creates a code, or saves an existing one (passed second). Resolve with the
	 * stored code to show its server id; reject to keep the dialog open.
	 */
	onSaveCode?: (draft: CreditCodeDraft, existing?: CreditCode) => Promise<CreditCode | void> | void;
	/** Creates a bulk batch of single-use codes. */
	onCreateCodes?: (drafts: CreditCodeDraft[]) => Promise<void> | void;
	/** Platform scope: places an admin hold. */
	onHoldDatabase?: (database: DatabaseStanding, note: string) => Promise<void> | void;
	/** Platform scope: lifts a suspension or hold. */
	onReleaseDatabase?: (database: DatabaseStanding) => Promise<void> | void;
	onAction?: (action: BillingConsoleAction) => void;
	theme?: BillingConsoleTheme;
	onThemeChange?: (theme: BillingConsoleTheme) => void;
	locale?: string;
	timeZone?: string;
	now?: string;
	defaultSidebarCollapsed?: boolean;
	/** Shows the workspace as a rounded frame on a canvas instead of filling its container. */
	framed?: boolean;
	className?: string;
};

const normalizeId = (code: string) => code.toLowerCase().replace(/[^a-z0-9]+/g, '-');

const ALL_VIEWS: BillingConsoleView[] = ['overview', 'catalog', 'customers', 'provider', 'standing'];

type LocalState = {
	plans: Plan[];
	meters: Meter[];
	packs: CreditPack[];
	codes: CreditCode[];
	settings: BillingConsoleSettings;
	health: BillingHealth;
	connection?: ProviderConnection;
	customers: CustomerSummary[];
	standing: DatabaseStanding[];
};

const initialState = (data: BillingConsoleData): LocalState => ({
	plans: data.plans,
	meters: data.meters,
	packs: data.packs,
	codes: data.codes,
	settings: data.settings,
	health: data.health,
	connection: data.connection,
	customers: data.customers,
	standing: data.standing ?? [],
});

/**
 * Billing Console template: the operator side of Constructive billing, for
 * the platform or a tenant database. Overview, catalog (plans and prices,
 * entitlements, meters, packs and codes), customers, the payment provider,
 * and (platform only) database standing. The host owns every write; the
 * console shows it optimistically once the host's promise resolves.
 */
function BillingConsole({
	data,
	view: viewProp,
	defaultView = 'overview',
	onViewChange,
	views: viewsProp,
	onSaveEntitlements,
	onConnectProvider,
	onRunReadinessCheck,
	onToggleBilling,
	onCreditRateChange,
	onGrantCredits,
	onSaveCode,
	onCreateCodes,
	onHoldDatabase,
	onReleaseDatabase,
	onAction,
	theme: themeProp,
	onThemeChange,
	locale,
	timeZone,
	now,
	defaultSidebarCollapsed,
	framed,
	className,
}: BillingConsoleProps) {
	const viewsKey = (viewsProp ?? ALL_VIEWS).filter((candidate) => candidate !== 'standing' || data.scope === 'platform').join('|');
	// Hosts often pass `views` inline; key it by content so the context stays stable.
	const views = React.useMemo(() => viewsKey.split('|') as BillingConsoleView[], [viewsKey]);
	const [requestedView, setView] = useControllableState<BillingConsoleView>({ prop: viewProp, defaultProp: defaultView, onChange: onViewChange });
	const view = views.includes(requestedView) ? requestedView : (views[0] ?? 'overview');
	const [theme, setTheme] = useControllableState<BillingConsoleTheme>({ prop: themeProp, defaultProp: 'system', onChange: onThemeChange });
	const [local, setLocal] = React.useState<LocalState>(() => initialState(data));
	const [source, setSource] = React.useState(data);
	if (source !== data) {
		setSource(data);
		setLocal(initialState(data));
	}
	const [checking, setChecking] = React.useState(false);
	const [connect, setConnect] = React.useState<{ open: boolean; providerId?: string }>({ open: false });
	// The sheet keeps its last customer while closing so its exit animation has content.
	const [customerId, setCustomerId] = React.useState<string | null>(null);
	const [customerOpen, setCustomerOpen] = React.useState(false);

	const handlers = useLatest({ onAction, onSaveEntitlements, onRunReadinessCheck, onToggleBilling, onCreditRateChange, onHoldDatabase, onReleaseDatabase, onSaveCode, onCreateCodes });
	const canSaveCode = Boolean(onSaveCode);
	const canCreateCodes = Boolean(onCreateCodes);
	const canHold = Boolean(onHoldDatabase);
	const canRelease = Boolean(onReleaseDatabase);

	const clock = React.useCallback(() => now ?? new Date().toISOString(), [now]);
	const provider = data.providers.find((candidate) => candidate.id === local.connection?.providerId);

	const context = React.useMemo<BillingConsoleContextValue>(() => {
		const planNames = new Map(local.plans.map((plan) => [plan.id, plan.displayName]));
		const meterNames = new Map(data.meters.map((meter) => [meter.slug, meter.displayName]));
		const emit = (action: BillingConsoleAction) => handlers.current.onAction?.(action);
		const setter =
			<K extends 'plans' | 'meters' | 'packs' | 'codes'>(key: K): React.Dispatch<React.SetStateAction<LocalState[K]>> =>
			(next) =>
				setLocal((current) => ({ ...current, [key]: typeof next === 'function' ? next(current[key]) : next }));
		const setStanding = (database: DatabaseStanding, patch: Partial<DatabaseStanding>) =>
			setLocal((current) => ({
				...current,
				standing: current.standing.map((candidate) => (candidate.id === database.id ? { ...candidate, ...patch } : candidate)),
			}));
		return {
			data,
			connection: local.connection,
			view,
			views,
			setView,
			emit,
			theme,
			setTheme,
			provider,
			plans: local.plans,
			setPlans: setter('plans'),
			meters: local.meters,
			setMeters: setter('meters'),
			packs: local.packs,
			setPacks: setter('packs'),
			codes: local.codes,
			setCodes: setter('codes'),
			saveCode: canSaveCode
				? async (draft, existing) => {
						const stored = await handlers.current.onSaveCode?.(draft, existing);
						const next: CreditCode = stored ?? {
							...existing,
							...draft,
							id: existing?.id ?? `code-${normalizeId(draft.code)}`,
							redemptions: existing?.redemptions ?? 0,
							createdAt: existing?.createdAt ?? clock(),
						};
						setLocal((current) => ({
							...current,
							codes: existing ? current.codes.map((code) => (code.id === existing.id ? next : code)) : [next, ...current.codes],
						}));
					}
				: undefined,
			createCodes: canCreateCodes
				? async (drafts) => {
						await handlers.current.onCreateCodes?.(drafts);
						const createdAt = clock();
						setLocal((current) => ({
							...current,
							codes: [...drafts.map((draft) => ({ ...draft, id: `code-${normalizeId(draft.code)}`, redemptions: 0, createdAt })), ...current.codes],
						}));
					}
				: undefined,
			saveEntitlements: async (changes) => {
				await handlers.current.onSaveEntitlements?.(changes);
			},
			holdDatabase: canHold
				? async (database, note) => {
						await handlers.current.onHoldDatabase?.(database, note);
						setStanding(database, { suspendedReason: 'admin', suspendedAt: clock(), note });
					}
				: undefined,
			releaseDatabase: canRelease
				? async (database) => {
						await handlers.current.onReleaseDatabase?.(database);
						setStanding(database, { suspendedReason: null, suspendedAt: null, note: undefined });
					}
				: undefined,
			settings: local.settings,
			health: local.health,
			checking,
			runCheck: async () => {
				setChecking(true);
				try {
					const verdict = await handlers.current.onRunReadinessCheck?.();
					if (verdict) setLocal((current) => ({ ...current, health: verdict }));
				} finally {
					setChecking(false);
				}
			},
			setBillingEnabled: async (enabled) => {
				// Mirrors the database gate so the refusal reads the same without a round trip.
				if (enabled && !(local.health.ready && isHealthFresh(local.health, clock()))) {
					throw new Error('Billing is not ready: run the readiness check and fix what fails first.');
				}
				await handlers.current.onToggleBilling?.(enabled);
				setLocal((current) => ({ ...current, settings: { ...current.settings, enableBilling: enabled } }));
			},
			setCreditRate: async (creditsPerCent) => {
				await handlers.current.onCreditRateChange?.(creditsPerCent);
				setLocal((current) => ({ ...current, settings: { ...current.settings, creditsPerCent } }));
			},
			openConnect: (providerId) => setConnect({ open: true, providerId }),
			standing: local.standing,
			openCustomer: (customer) => {
				setCustomerId(customer.id);
				setCustomerOpen(true);
				emit({ type: 'open-customer', customerId: customer.id });
			},
			planName: (id) => planNames.get(id) ?? humanize(id),
			meterName: (slug) => meterNames.get(slug) ?? humanize(slug),
		};
	}, [canCreateCodes, canHold, canRelease, canSaveCode, checking, clock, data, handlers, local, provider, setTheme, setView, theme, view, views]);

	const customer = local.customers.find((candidate) => candidate.id === customerId);

	return (
		<BillingFormatProvider locale={locale} timeZone={timeZone} now={now}>
			<BillingConsoleContext.Provider value={context}>
				<WorkspaceShell
					slot="billing-console"
					className={className}
					defaultSidebarCollapsed={defaultSidebarCollapsed}
					framed={framed}
					sidebar={({ mode, collapsed, onCollapsedChange, onNavigate }) => (
						<BillingConsoleSidebar drawer={mode === 'drawer'} collapsed={collapsed} onCollapsedChange={onCollapsedChange} onNavigate={mode === 'drawer' ? onNavigate : undefined} />
					)}
				>
					{view === 'overview' ? <ConsoleOverviewView /> : null}
					{view === 'catalog' ? <ConsoleCatalogView /> : null}
					{view === 'customers' ? <ConsoleCustomersView /> : null}
					{view === 'provider' ? <ConsoleProviderView /> : null}
					{view === 'standing' ? <ConsoleStandingView /> : null}
				</WorkspaceShell>
				<ProviderConnectDialog
					providers={data.providers}
					activeProviderId={local.connection?.providerId}
					connection={local.connection}
					initialProviderId={connect.providerId}
					open={connect.open}
					onOpenChange={(open) => setConnect((current) => ({ ...current, open }))}
					onConnect={async (providerId, values) => {
						await onConnectProvider?.(providerId, values);
						const detected = data.providers.find((candidate) => candidate.id === providerId)?.detectMode?.(values) ?? null;
						setLocal((current) => {
							const same = current.connection?.providerId === providerId;
							const credentials = { ...(same ? current.connection?.credentials : {}) };
							for (const name of Object.keys(values)) credentials[name] = { set: true, updatedAt: clock() };
							return {
								...current,
								connection: {
									providerId,
									mode: detected ?? (same ? current.connection!.mode : 'test'),
									accountLabel: same ? current.connection?.accountLabel : undefined,
									accountId: same ? current.connection?.accountId : undefined,
									connectedAt: same ? current.connection?.connectedAt : clock(),
									credentials,
								},
								health: same ? current.health : { ...current.health, ready: false },
								settings: same ? current.settings : { ...current.settings, enableBilling: false },
							};
						});
					}}
				/>
				<CustomerDetailSheet
					open={customerOpen}
					onOpenChange={setCustomerOpen}
					customer={customer}
					plans={local.plans}
					meters={local.meters}
					provider={provider}
					mode={local.connection?.mode}
					onGrantCredits={
						onGrantCredits
							? async (request) => {
									await onGrantCredits(request);
									setLocal((current) => ({
										...current,
										customers: current.customers.map((candidate) =>
											candidate.id === request.customerId && candidate.detail
												? {
														...candidate,
														detail: {
															...candidate.detail,
															grants: [
																{
																	id: `grant-${candidate.detail.grants.length + 1}`,
																	meterSlug: request.meterSlug,
																	amount: request.amount,
																	remaining: request.amount,
																	creditType: request.creditType,
																	source: 'admin',
																	reason: request.reason,
																	createdAt: clock(),
																	expiresAt: request.expiresInDays ? new Date(new Date(clock()).getTime() + request.expiresInDays * DAY).toISOString() : undefined,
																},
																...candidate.detail.grants,
															],
														},
													}
												: candidate,
										),
									}));
								}
							: undefined
					}
					onRemoveOverride={(target, override) => {
						setLocal((current) => ({
							...current,
							customers: current.customers.map((candidate) =>
								candidate.id === target.id && candidate.detail ? { ...candidate, detail: { ...candidate.detail, overrides: candidate.detail.overrides.filter((row) => row.id !== override.id) } } : candidate,
							),
						}));
						onAction?.({ type: 'remove-override', customerId: target.id, overrideId: override.id });
					}}
					onCancelScheduledChange={(target) => {
						setLocal((current) => ({
							...current,
							customers: current.customers.map((candidate) => (candidate.id === target.id ? { ...candidate, scheduledChange: undefined } : candidate)),
						}));
						onAction?.({ type: 'cancel-scheduled-change', customerId: target.id });
					}}
				/>
			</BillingConsoleContext.Provider>
		</BillingFormatProvider>
	);
}

export { BillingConsole };
export type { BillingConsoleProps };

'use client';

import { Package, Plus } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { CreditPackTable, EntitlementMatrix, entitlementKey, MeterCatalogTable, PlanPriceTable } from '@/components/ui/billing-kit/catalog';
import type { EntitlementRow } from '@/components/ui/billing-kit/plan';
import { SectionHeading } from '@/components/ui/billing-kit/surface';
import type { Plan } from '@/components/ui/billing-kit/types';
import { FilterGroup, ViewFrame } from '@/components/ui/workspace-kit/primitives';
import { startViewTransition, ViewAnimation } from '@/components/ui/workspace-kit/view-transition';
import { useBillingConsole } from '@/components/ui/billing-console/billing-console-context';
import { ConsoleCodesTab } from '@/components/ui/billing-console/codes-tab';
import type { EntitlementChange } from '@/components/ui/billing-console/types';

type Tab = 'plans' | 'entitlements' | 'meters' | 'packs' | 'codes';

/** Applies unsaved entitlement edits on top of the saved plans. */
function applyChanges(plans: Plan[], changes: ReadonlyMap<string, EntitlementChange>): Plan[] {
	if (changes.size === 0) return plans;
	return plans.map((plan) => {
		let next = plan;
		for (const change of changes.values()) {
			if (change.planId !== plan.id) continue;
			const field = change.kind === 'limit' ? 'limits' : change.kind === 'meter' ? 'meterLimits' : 'caps';
			next = { ...next, [field]: { ...next[field], [change.key]: change.value } };
		}
		return next;
	});
}

function readSaved(plan: Plan | undefined, row: EntitlementRow) {
	return plan ? (row.kind === 'limit' ? plan.limits : row.kind === 'meter' ? plan.meterLimits : plan.caps)[row.key] : undefined;
}

type SaveState = { kind: 'idle' | 'saving' | 'saved' } | { kind: 'error'; message: string };

type EntitlementsTabProps = {
	/** Unsaved edits, owned by the catalog so switching tabs keeps them. */
	changes: ReadonlyMap<string, EntitlementChange>;
	onChangesChange: (changes: Map<string, EntitlementChange>) => void;
};

function EntitlementsTab({ changes, onChangesChange }: EntitlementsTabProps) {
	const { plans, setPlans, data, saveEntitlements } = useBillingConsole();
	const [state, setState] = React.useState<SaveState>({ kind: 'idle' });
	const shown = React.useMemo(() => applyChanges(plans, changes).filter((plan) => plan.active), [changes, plans]);
	const dirty = React.useMemo(() => new Set(changes.keys()), [changes]);

	const save = async () => {
		setState({ kind: 'saving' });
		try {
			await saveEntitlements([...changes.values()]);
			setPlans((current) => applyChanges(current, changes));
			onChangesChange(new Map());
			setState({ kind: 'saved' });
		} catch (reason) {
			setState({ kind: 'error', message: reason instanceof Error ? reason.message : 'Saving failed.' });
		}
	};

	return (
		<div className="flex flex-col gap-3">
			<SectionHeading
				title="Entitlements"
				description="What each plan grants. Saving applies to new subscriptions right away and to existing ones through the plan cascade."
			/>
			<EntitlementMatrix
				plans={shown}
				groups={data.entitlementGroups}
				dirty={dirty}
				onChange={(planId, row, value) => {
					const next = new Map(changes);
					const key = entitlementKey(planId, row);
					if (readSaved(plans.find((plan) => plan.id === planId), row) === value) next.delete(key);
					else next.set(key, { planId, kind: row.kind, key: row.key, value });
					onChangesChange(next);
					setState({ kind: 'idle' });
				}}
			/>
			<div
				role="region"
				aria-label="Unsaved changes"
				aria-live="polite"
				className={cn(
					'sticky bottom-3 z-20 flex flex-wrap items-center gap-3 self-center rounded-xl border border-border bg-card/95 px-3 py-2 shadow-lg backdrop-blur-sm',
					changes.size === 0 && state.kind !== 'saved' && 'invisible',
				)}
			>
				<span className="text-[0.8125rem] text-foreground tabular-nums">
					{state.kind === 'saved' && changes.size === 0 ? 'Entitlements saved' : `${changes.size} unsaved ${changes.size === 1 ? 'change' : 'changes'}`}
				</span>
				{state.kind === 'error' ? <span className="text-xs text-destructive">{state.message}</span> : null}
				{changes.size > 0 ? (
					<>
						<Button
							size="xs"
							variant="ghost"
							disabled={state.kind === 'saving'}
							onClick={() => {
								onChangesChange(new Map());
								setState({ kind: 'idle' });
							}}
						>
							Discard
						</Button>
						<Button size="xs" disabled={state.kind === 'saving'} aria-busy={state.kind === 'saving' || undefined} onClick={save}>
							{state.kind === 'saving' ? 'Saving…' : 'Save changes'}
						</Button>
					</>
				) : null}
			</div>
		</div>
	);
}

/**
 * The catalog an operator sells from: plans and their prices (mirrored to
 * the provider), the entitlement matrix, the meter catalog, and credit packs
 * and promo codes.
 */
export function ConsoleCatalogView() {
	const { data, connection, plans, setPlans, meters, setMeters, packs, setPacks, codes, emit, provider, settings } = useBillingConsole();
	const [tab, setTab] = React.useState<Tab>('plans');
	const [changes, setChanges] = React.useState<Map<string, EntitlementChange>>(() => new Map());
	const subscribers = React.useMemo(() => {
		const counts: Record<string, number> = {};
		for (const customer of data.customers) counts[customer.planId] = (counts[customer.planId] ?? 0) + 1;
		return counts;
	}, [data.customers]);

	const actions =
		tab === 'plans' ? (
			<Button size="xs" variant="outline" onClick={() => emit({ type: 'new-plan' })}>
				<Plus aria-hidden="true" />
				New plan
			</Button>
		) : tab === 'packs' ? (
			<Button size="xs" variant="outline" onClick={() => emit({ type: 'new-pack' })}>
				<Plus aria-hidden="true" />
				New pack
			</Button>
		) : null;

	return (
		<ViewFrame icon={Package} title="Catalog" actions={actions}>
			<FilterGroup
				label="Catalog section"
				value={tab}
				onChange={(next) => startViewTransition(() => setTab(next))}
				options={[
					{ value: 'plans', label: 'Plans & prices', count: plans.length },
					{ value: 'entitlements', label: 'Entitlements' },
					{ value: 'meters', label: 'Meters', count: meters.filter((meter) => meter.meterType !== 'usage_pool').length },
					{ value: 'packs', label: 'Credit packs', count: packs.length },
					{ value: 'codes', label: 'Gift codes', count: codes.length },
				]}
			/>
			<ViewAnimation>
				<div key={tab} className="flex flex-col gap-6">
					{tab === 'plans' ? (
						<div className="flex flex-col gap-3">
							<SectionHeading
								title="Plans and prices"
								description={
									provider?.immutablePrices
										? `Prices are immutable once ${provider.name} has them: add a new price and retire the old one instead of editing it.`
										: `Each plan's prices and how they mirror to ${provider?.name ?? 'the provider'}. Retire a price rather than removing it so current subscribers keep theirs.`
								}
							/>
							<PlanPriceTable
								plans={plans}
								provider={provider}
								mode={connection?.mode}
								subscribers={subscribers}
								onTogglePlan={(plan, active) => {
									setPlans((current) => current.map((candidate) => (candidate.id === plan.id ? { ...candidate, active, syncState: 'pending' } : candidate)));
									emit({ type: 'toggle-plan', planId: plan.id, active });
								}}
								onTogglePrice={(plan, price, active) => {
									setPlans((current) =>
										current.map((candidate) =>
											candidate.id === plan.id
												? { ...candidate, prices: candidate.prices.map((row) => (row.id === price.id ? { ...row, active, syncState: 'pending' } : row)) }
												: candidate,
										),
									);
									emit({ type: 'toggle-price', planId: plan.id, priceId: price.id, active });
								}}
								onAddPrice={(plan) => emit({ type: 'add-price', planId: plan.id })}
							/>
						</div>
					) : null}
					{tab === 'entitlements' ? <EntitlementsTab changes={changes} onChangesChange={setChanges} /> : null}
					{tab === 'meters' ? (
						<div className="flex flex-col gap-3">
							<SectionHeading title="Meters" description="Every billable dimension, grouped by the pool it falls back to. Credit cost is what one unit costs once its own allowance is gone." />
							<MeterCatalogTable
								meters={meters}
								onToggle={(meter, active) => {
									setMeters((current) => current.map((candidate) => (candidate.slug === meter.slug ? { ...candidate, active } : candidate)));
									emit({ type: 'toggle-meter', meterSlug: meter.slug, active });
								}}
							/>
						</div>
					) : null}
					{tab === 'codes' ? <ConsoleCodesTab /> : null}
					{tab === 'packs' ? (
						<>
							<div className="flex flex-col gap-3">
								<SectionHeading
									title="Credit packs"
									description={`One-off purchases. The charge follows the credit rate (${settings.creditsPerCent} ${settings.creditsPerCent === 1 ? 'credit' : 'credits'} per cent), so a pack advertised below it is refused at checkout.`}
								/>
								<CreditPackTable
									packs={packs}
									creditsPerCent={settings.creditsPerCent}
									onToggle={(pack, active) => {
										setPacks((current) => current.map((candidate) => (candidate.id === pack.id ? { ...candidate, active } : candidate)));
										emit({ type: 'toggle-pack', packId: pack.id, active });
									}}
								/>
							</div>
						</>
					) : null}
				</div>
			</ViewAnimation>
		</ViewFrame>
	);
}

