					{row('standing', 'Standing', ShieldAlert, suspended > 0 ? <NavCount value={suspended} tone="danger" /> : null, suspended > 0 ? `${suspended} suspended` : undefined)}
				</NavSection>
			</nav>
		</SidebarFrame>
	);
}

'use client';

import { ShieldAlert } from 'lucide-react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Dialog, DialogDescription, DialogFooter, DialogHeader, DialogPopup, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { SUSPENSION_REASON } from '@/components/ui/billing-kit/format';
import { StandingTable } from '@/components/ui/billing-kit/standing';
import { type DatabaseStanding } from '@/components/ui/billing-kit/types';
